// Purpose: Orchestrates the DIP workflow for Q aG ov er na nc eA dm in is tr at io nS er vi ce.
using System.Text.Json;
using Dip.Application.Abstractions.Persistence;
using Dip.Application.Abstractions.Observability;
using Dip.Application.Abstractions.Time;
using Dip.Domain.Entities;
using Dip.Domain.Enums;
using Dip.Application.Features.Authorization;

namespace Dip.Application.Features.QualityGovernance;

/// <summary>Human governance mutations only. Actor identity is supplied by the authenticated server context, never by request JSON.</summary>
public sealed class QaGovernanceAdministrationService(IQaGovernanceRepository repo,IAuditLogRepository audit,IUnitOfWork uow,ISystemClock clock,IDipOperationalMetrics metrics,IProjectMutationCoordinator mutations)
{
    public async Task TransitionAsync(TransitionFindingCommand command,GovernanceAuditContext actor,CancellationToken ct)
    {
        var state=await repo.FindFindingStateAsync(command.ProjectId,command.Fingerprint,ct)??throw new KeyNotFoundException("Finding state not found.");CheckVersion(command.ExpectedVersion,state.Version);var before=Snapshot(state);state.Transition(command.Status,command.Reason,actor.Actor,clock.UtcNow);await AddAudit(command.ProjectId,"finding.lifecycle","transition",actor,command.Fingerprint,before,Snapshot(state),command.Reason,ct);await uow.SaveChangesAsync(ct);
    }
    public async Task<Guid> RequestWaiverAsync(CreateWaiverCommand command,GovernanceAuditContext actor,CancellationToken ct)
    {
        if(string.IsNullOrWhiteSpace(command.Fingerprint)&&string.IsNullOrWhiteSpace(command.RuleId)&&string.IsNullOrWhiteSpace(command.PathPattern))throw new ArgumentException("A waiver must target a fingerprint, rule, or path.");
        var waiver=new QaWaiver(Guid.NewGuid(),command.ProjectId,command.Name,command.Reason,actor.Actor,command.Fingerprint,command.RuleId,command.PathPattern,clock.UtcNow,command.ExpiresAtUtc);await repo.AddWaiverAsync(waiver,ct);await AddAudit(command.ProjectId,"waiver","request",actor,waiver.Id.ToString(),null,Snapshot(waiver),command.Reason,ct);await uow.SaveChangesAsync(ct);return waiver.Id;
    }
    public Task ApproveWaiverAsync(Guid id,DecideWaiverCommand decision,GovernanceAuditContext actor,CancellationToken ct)=>DecideWaiverAsync(id,decision,actor,true,ct);
    public Task RejectWaiverAsync(Guid id,DecideWaiverCommand decision,GovernanceAuditContext actor,CancellationToken ct)=>DecideWaiverAsync(id,decision,actor,false,ct);
    private async Task DecideWaiverAsync(Guid id,DecideWaiverCommand decision,GovernanceAuditContext actor,bool approve,CancellationToken ct){var waiver=await repo.GetWaiverAsync(id,ct)??throw new KeyNotFoundException("Waiver not found.");CheckVersion(decision.ExpectedVersion,waiver.Version);var before=Snapshot(waiver);if(approve)waiver.Approve(actor.Actor,decision.Reason,clock.UtcNow);else waiver.Reject(actor.Actor,decision.Reason,clock.UtcNow);await AddAudit(waiver.ProjectId,"waiver",approve?"approve":"reject",actor,id.ToString(),before,Snapshot(waiver),decision.Reason,ct);await uow.SaveChangesAsync(ct);}
    public async Task RevokeWaiverAsync(Guid id,DecideWaiverCommand decision,GovernanceAuditContext actor,CancellationToken ct){var waiver=await repo.GetWaiverAsync(id,ct)??throw new KeyNotFoundException("Waiver not found.");CheckVersion(decision.ExpectedVersion,waiver.Version);var before=Snapshot(waiver);waiver.Revoke(actor.Actor,decision.Reason,clock.UtcNow);await AddAudit(waiver.ProjectId,"waiver","revoke",actor,id.ToString(),before,Snapshot(waiver),decision.Reason,ct);await uow.SaveChangesAsync(ct);}
    public async Task RebaselineAsync(RebaselineQaCommand command,GovernanceAuditContext actor,CancellationToken ct){var baseline=await repo.FindBaselineAsync(command.ProjectId,command.SubjectKey,command.MetricKey,ct);var before=baseline is null?null:Snapshot(baseline);if(baseline is null){baseline=new QaRegressionBaseline(Guid.NewGuid(),command.ProjectId,command.SubjectKey,command.MetricKey,command.CommitSha,command.Value,clock.UtcNow);await repo.AddBaselineAsync(baseline,ct);}else baseline.Rebaseline(command.CommitSha,command.Value,clock.UtcNow);await AddAudit(command.ProjectId,"baseline","rebaseline",actor,$"{command.SubjectKey}:{command.MetricKey}",before,Snapshot(baseline),"Explicit baseline change",ct);await uow.SaveChangesAsync(ct);}
    public async Task<Guid> AddOwnershipRuleAsync(CreateOwnershipRuleCommand command,GovernanceAuditContext actor,CancellationToken ct){var x=new QaOwnershipRule(Guid.NewGuid(),command.ProjectId,command.Name,command.PathPattern,command.Team,command.Workstream,command.Priority,command.Enabled,clock.UtcNow);await repo.AddOwnershipRuleAsync(x,ct);await AddAudit(command.ProjectId,"ownership","create",actor,x.Id.ToString(),null,Snapshot(x),"Ownership rule created",ct);await uow.SaveChangesAsync(ct);return x.Id;}
    public async Task<Guid> CreatePolicyAsync(CreateQaPolicyCommand command,GovernanceAuditContext actor,CancellationToken ct)
    {
        var existing=(await repo.ListPoliciesAsync(command.ProjectId,ct)).FirstOrDefault(x=>string.Equals(x.Version,command.Version,StringComparison.OrdinalIgnoreCase));if(existing is not null)throw new InvalidOperationException($"Policy version '{command.Version}' already exists for this project.");
        var x=new QaPolicy(Guid.NewGuid(),command.ProjectId,command.Name,command.Version,JsonSerializer.Serialize(command.Rules),false,clock.UtcNow);await repo.AddPolicyAsync(x,ct);await AddAudit(command.ProjectId,"policy","create.draft",actor,x.Id.ToString(),null,Snapshot(x),"Policy version created as Draft; approval and activation are separate privileged actions.",ct);await uow.SaveChangesAsync(ct);return x.Id;
    }
    public async Task ApprovePolicyAsync(Guid id,PolicyLifecycleCommand command,GovernanceAuditContext actor,CancellationToken ct){var x=await repo.GetPolicyAsync(id,ct)??throw new KeyNotFoundException("QA policy not found.");CheckVersion(command.ExpectedVersion,x.ConcurrencyVersion);var before=Snapshot(x);x.Approve(actor.Actor,clock.UtcNow);await AddAudit(x.ProjectId,"policy","approve",actor,id.ToString(),before,Snapshot(x),command.Reason,ct);await uow.SaveChangesAsync(ct);}
    public async Task ActivatePolicyAsync(Guid id,PolicyLifecycleCommand command,GovernanceAuditContext actor,CancellationToken ct)
    {
        var target=await repo.GetPolicyAsync(id,ct)??throw new KeyNotFoundException("QA policy not found.");var projectId=target.ProjectId;
        await mutations.ExecuteAsync(projectId,async token=>{var x=await repo.GetPolicyAsync(id,token)??throw new KeyNotFoundException("QA policy not found.");CheckVersion(command.ExpectedVersion,x.ConcurrencyVersion);var before=Snapshot(x);var active=await repo.GetActivePolicyAsync(projectId,token);if(active is not null&&active.Id!=x.Id)active.Supersede(clock.UtcNow);var revision=(await repo.ListPoliciesAsync(projectId,token)).Select(v=>v.Revision).DefaultIfEmpty(0).Max()+1;x.Activate(actor.Actor,active?.Id,revision,clock.UtcNow);await AddAudit(projectId,"policy","activate",actor,id.ToString(),before,Snapshot(x),command.Reason,token);await uow.SaveChangesAsync(token);},ct);
    }
    public async Task ArchivePolicyAsync(Guid id,PolicyLifecycleCommand command,GovernanceAuditContext actor,CancellationToken ct){var x=await repo.GetPolicyAsync(id,ct)??throw new KeyNotFoundException("QA policy not found.");CheckVersion(command.ExpectedVersion,x.ConcurrencyVersion);var before=Snapshot(x);x.Archive(clock.UtcNow);await AddAudit(x.ProjectId,"policy","archive",actor,id.ToString(),before,Snapshot(x),command.Reason,ct);await uow.SaveChangesAsync(ct);}
    public async Task<Guid> AddTestImpactRuleAsync(CreateTestImpactRuleCommand command,GovernanceAuditContext actor,CancellationToken ct){using var _=JsonDocument.Parse(command.CommandJson);var x=new QaTestImpactRule(Guid.NewGuid(),command.ProjectId,command.PathPattern,command.TestKey,command.CommandJson,command.Priority,command.Enabled,clock.UtcNow);await repo.AddTestImpactRuleAsync(x,ct);await AddAudit(command.ProjectId,"test-impact","create",actor,x.Id.ToString(),null,Snapshot(x),"Test impact rule created",ct);await uow.SaveChangesAsync(ct);return x.Id;}
    public async Task<Guid> AddRetentionRuleAsync(CreateRetentionRuleCommand command,GovernanceAuditContext actor,CancellationToken ct){var x=new QaArtifactRetentionRule(Guid.NewGuid(),command.ProjectId,command.KindPattern,command.RetentionClass,command.RetentionDays,command.PreserveOnCritical,command.Enabled,clock.UtcNow);await repo.AddRetentionRuleAsync(x,ct);await AddAudit(command.ProjectId,"retention","create",actor,x.Id.ToString(),null,Snapshot(x),"Retention rule created",ct);await uow.SaveChangesAsync(ct);return x.Id;}
    public async Task<Guid> RequestOverrideAsync(RequestReleaseGateOverrideCommand command,GovernanceAuditContext actor,CancellationToken ct){var latest=await repo.GetLatestPolicyEvaluationAsync(command.ProjectId,ct);if(latest is null)throw new InvalidOperationException("A release gate evaluation must exist before an override can be requested.");if(latest.Verdict==QaGateVerdict.Go)throw new InvalidOperationException("GO evaluations do not require an override.");if(command.PolicyEvaluationId.HasValue&&command.PolicyEvaluationId.Value!=latest.Id)throw new InvalidOperationException("Override must target the latest policy evaluation.");var provenance=await repo.GetLatestProvenanceAsync(command.ProjectId,ct);var targetCommit=string.IsNullOrWhiteSpace(command.CommitSha)?provenance?.CommitSha:command.CommitSha;if(string.IsNullOrWhiteSpace(targetCommit))throw new InvalidOperationException("Release override requires an exact commit SHA from the request or latest QA provenance.");var x=new QaReleaseGateOverride(Guid.NewGuid(),command.ProjectId,latest.Id,command.QaRunId??latest.QaRunId,targetCommit,command.Reason,actor.Actor,clock.UtcNow,command.ExpiresAtUtc);await repo.AddReleaseOverrideAsync(x,ct);await AddAudit(command.ProjectId,"release-gate","override.request",actor,x.Id.ToString(),null,Snapshot(x),command.Reason,ct);await uow.SaveChangesAsync(ct);return x.Id;}
    public Task ApproveOverrideAsync(Guid id,DecideReleaseGateOverrideCommand command,GovernanceAuditContext actor,CancellationToken ct)=>DecideOverrideAsync(id,command,actor,"approve",ct);
    public Task RejectOverrideAsync(Guid id,DecideReleaseGateOverrideCommand command,GovernanceAuditContext actor,CancellationToken ct)=>DecideOverrideAsync(id,command,actor,"reject",ct);
    public Task RevokeOverrideAsync(Guid id,DecideReleaseGateOverrideCommand command,GovernanceAuditContext actor,CancellationToken ct)=>DecideOverrideAsync(id,command,actor,"revoke",ct);
    private async Task DecideOverrideAsync(Guid id,DecideReleaseGateOverrideCommand command,GovernanceAuditContext actor,string action,CancellationToken ct){var x=await repo.GetReleaseOverrideAsync(id,ct)??throw new KeyNotFoundException("Release override not found.");CheckVersion(command.ExpectedVersion,x.Version);var before=Snapshot(x);if(action=="approve")x.Approve(actor.Actor,command.Reason,clock.UtcNow);else if(action=="reject")x.Reject(actor.Actor,command.Reason,clock.UtcNow);else x.Revoke(actor.Actor,command.Reason,clock.UtcNow);await AddAudit(x.ProjectId,"release-gate",$"override.{action}",actor,id.ToString(),before,Snapshot(x),command.Reason,ct);await uow.SaveChangesAsync(ct);}
    public async Task<Guid> RecordBackupVerificationAsync(RecordBackupVerificationCommand command,GovernanceAuditContext actor,CancellationToken ct){var x=new QaBackupVerificationRecord(Guid.NewGuid(),command.ProjectId,command.BackupKind,command.BackupReference,command.SourceCommit,command.EnvironmentFingerprint,command.Status,command.Detail,clock.UtcNow);await repo.AddBackupVerificationAsync(x,ct);await AddAudit(command.ProjectId,"backup-restore","verification.record",actor,x.Id.ToString(),null,Snapshot(x),command.Detail,ct);await uow.SaveChangesAsync(ct);return x.Id;}
    private Task AddAudit(Guid projectId,string category,string action,GovernanceAuditContext actor,string? subject,string? before,string? after,string reason,CancellationToken ct){metrics.GovernanceMutation($"{category}.{action}","attempted");return audit.AddAsync(new AuditLog(Guid.NewGuid(),projectId,category,action,actor.Actor,subject,JsonSerializer.Serialize(new{before,after}),clock.UtcNow,actor.RequestId,actor.CorrelationId,reason),ct);}
    private static string Snapshot<T>(T value)=>JsonSerializer.Serialize(value);
    private static void CheckVersion(long? expected,long actual){if(expected.HasValue&&expected.Value!=actual)throw new InvalidOperationException($"Concurrency conflict. Expected version {expected.Value}, current version {actual}.");}
}
